const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const SAVE='wildwhim-save-v1';
const defaults={name:'Little Wanderer',hair:'🧑🏻‍🌾',coat:'#e68f71',berries:3,steps:0,friends:[],met:[],started:false};
let save={...defaults,...JSON.parse(localStorage.getItem(SAVE)||'{}')};
const species=[
 {id:'moonmoss',name:'Moonmoss',kind:'Lunar lamb',emoji:'🌙',x:595,y:365,color:'#d9e8ba',shy:true,blurb:'A little lamb with a moonflower growing on its head. It collects soft, shiny things.'},
 {id:'puddlewing',name:'Puddlewing',kind:'Raincloud duckling',emoji:'🐣',x:780,y:460,color:'#abdfe0',blurb:'Part cloud, part duckling, all daydream. It makes tiny rainbows when it giggles.'},
 {id:'bramblekit',name:'Bramblekit',kind:'Thorn-tailed fox',emoji:'🦊',x:278,y:280,color:'#e6ab83',blurb:'A fox cub with a rosebud tail. It leaves flowers wherever its paws go.'}
];
let player={x:390,y:470,dir:1,walk:0},keys={},touchDirs={},target=null,lastTime=0,time=0,toastTimer,dialogueTarget=null,nearbyCreature=null;
const saveIt=()=>{localStorage.setItem(SAVE,JSON.stringify(save));renderUI()};
function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(canvas.width/1000,0,0,canvas.height/700,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function roundRect(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawWorld(dt){let W=1000,H=700;time+=dt;ctx.clearRect(0,0,W,H);
// layered meadow and soft distant hills
let sky=ctx.createLinearGradient(0,0,0,700);sky.addColorStop(0,'#b8d9d4');sky.addColorStop(.43,'#cee2b1');sky.addColorStop(1,'#a9cf91');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
ctx.fillStyle='#98c8a9';ctx.beginPath();ctx.moveTo(0,235);ctx.quadraticCurveTo(170,110,335,220);ctx.quadraticCurveTo(500,100,690,210);ctx.quadraticCurveTo(835,112,1000,208);ctx.lineTo(1000,410);ctx.lineTo(0,410);ctx.fill();
ctx.fillStyle='#a5d19b';ctx.beginPath();ctx.moveTo(0,305);ctx.quadraticCurveTo(190,205,390,310);ctx.quadraticCurveTo(645,192,820,292);ctx.quadraticCurveTo(930,245,1000,284);ctx.lineTo(1000,700);ctx.lineTo(0,700);ctx.fill();
// sun and clouds
ellipse(855,105,43,43,'#f8eab0');ellipse(855,105,34,34,'#fff2be');
function cloud(x,y,s){ellipse(x,y,42*s,17*s,'#f4f4dc');ellipse(x-26*s,y+4*s,24*s,15*s,'#f4f4dc');ellipse(x+25*s,y+1*s,25*s,17*s,'#f4f4dc')};cloud(195+Math.sin(time*.12)*12,115,.8);cloud(575-Math.sin(time*.1)*15,150,.58);
// far tree clusters
function tree(x,y,s,shade){ctx.fillStyle='#876b54';roundRect(ctx,x-8*s,y-30*s,16*s,48*s,6,'#907554');ellipse(x,y-48*s,36*s,40*s,shade);ellipse(x-21*s,y-31*s,22*s,27*s,shade);ellipse(x+20*s,y-27*s,25*s,28*s,shade);ellipse(x-7*s,y-65*s,15*s,18*s,'#d7e6a5')}
[[35,319,.95,'#638d6f'],[117,283,.75,'#719a70'],[936,312,.94,'#628b69'],[870,280,.7,'#749e72']].forEach(t=>tree(...t));
// meandering path
ctx.beginPath();ctx.moveTo(0,525);ctx.bezierCurveTo(190,465,255,620,450,579);ctx.bezierCurveTo(655,535,710,466,1000,520);ctx.lineTo(1000,700);ctx.lineTo(0,700);ctx.closePath();ctx.fillStyle='#d9c99b';ctx.fill();ctx.beginPath();ctx.moveTo(0,535);ctx.bezierCurveTo(200,476,257,633,452,592);ctx.bezierCurveTo(671,546,718,478,1000,532);ctx.strokeStyle='#e8d9ad';ctx.lineWidth=10;ctx.stroke();
// tiny pond
ellipse(776,463,94,34,'#79c5c6');ellipse(776,459,76,23,'#9bdbd4');ellipse(746,454,19,4,'#d7f0dd');ellipse(805,466,12,3,'#d7f0dd');
// grass flecks, flowers
for(let i=0;i<78;i++){let x=(i*173+43)%1000,y=245+(i*97)%420; if(y>445&&y<625&&x>180&&x<730)continue;ctx.strokeStyle=i%3?'#7fb17b':'#f1eab5';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y-7);ctx.moveTo(x,y);ctx.lineTo(x+4,y-8);ctx.stroke();if(i%5===0){ellipse(x,y-7,3,3,'#f7d5a5')}}
// clover patches and stones
for(let i=0;i<9;i++){let x=(i*137+87)%960+20,y=330+(i*71)%330;ellipse(x,y,4,3,'#6fa272');ellipse(x+5,y-3,4,3,'#79ac78');ellipse(x+8,y+2,4,3,'#71a371')}
// footpath stones
for(let i=0;i<13;i++){let x=40+i*78,y=566+Math.sin(i*.88)*40;ellipse(x,y,11,5,'#c8bd98')}
// creatures + twinkle
for(const c of species){let bob=Math.sin(time*2.2+c.x*.02)*4;let x=c.x,y=c.y+bob;ellipse(x,y+21,28,8,'#44675235');ctx.font='43px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(c.emoji,x,y);if(!save.friends.includes(c.id)&&c.id==='moonmoss'){ctx.font='15px system-ui';ctx.fillText('✦',x+22,y-25+Math.sin(time*2)*3)}if(save.friends.includes(c.id)){ctx.font='13px system-ui';ctx.fillText('♡',x+25,y-23+Math.sin(time*3)*3)}}
// player shadow + character
ellipse(player.x,player.y+22,21,7,'#45634a48');let step=Math.sin(player.walk*12)*2;ctx.save();ctx.translate(player.x,player.y);ctx.font='35px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(save.hair,0,-1+Math.abs(step));ctx.fillStyle=save.coat;ctx.beginPath();ctx.ellipse(0,12+Math.abs(step),12,8,0,0,Math.PI*2);ctx.fill();ctx.restore();
// ambient sparkles
for(let i=0;i<12;i++){let x=(i*91+time*8)%1000,y=220+(i*173)%430;ctx.globalAlpha=.35+Math.sin(time*2+i)*.3;ctx.fillStyle='#fff5bd';ctx.font='12px serif';ctx.fillText('✧',x,y)}ctx.globalAlpha=1;
}
function frame(ts){let dt=Math.min((ts-lastTime)/1000||0,.05);lastTime=ts;let dx=0,dy=0;if(keys.ArrowLeft||keys.a||touchDirs.left)dx--;if(keys.ArrowRight||keys.d||touchDirs.right)dx++;if(keys.ArrowUp||keys.w||touchDirs.up)dy--;if(keys.ArrowDown||keys.s||touchDirs.down)dy++;if(target){let tx=target.x-player.x,ty=target.y-player.y;if(Math.hypot(tx,ty)>15){dx+=tx/Math.hypot(tx,ty);dy+=ty/Math.hypot(tx,ty)}else target=null}let mag=Math.hypot(dx,dy);if(mag){dx/=mag;dy/=mag;player.x=clamp(player.x+dx*158*dt,35,965);player.y=clamp(player.y+dy*158*dt,225,658);player.walk+=dt;player.dir=dx>=0?1:-1;save.steps+=dt*mag*1.6;document.getElementById('steps').textContent=Math.floor(save.steps)}
drawWorld(dt);let near=species.filter(c=>Math.hypot(c.x-player.x,c.y-player.y)<108).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(near!==nearbyCreature){nearbyCreature=near;renderNearby()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*1000,y=(e.clientY-r.top)/r.height*700;let c=species.find(c=>Math.hypot(c.x-x,c.y-y)<65);if(c){if(Math.hypot(c.x-player.x,c.y-player.y)<112)openMeet(c);else target={x:c.x-48,y:c.y+45}}else target={x,y}});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '||e.key==='Enter')hello()});window.addEventListener('keyup',e=>keys[e.key]=false);
document.querySelectorAll('.dpad button').forEach(b=>{let d=b.dataset.dir;const on=e=>{e.preventDefault();touchDirs[d]=true},off=e=>{e.preventDefault();touchDirs[d]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});
document.getElementById('touchAct').addEventListener('click',hello);

function renderUI(){document.getElementById('playerName').textContent=save.name;document.getElementById('avatar').textContent=save.hair;document.getElementById('berryCount').textContent=save.berries;document.getElementById('steps').textContent=Math.floor(save.steps);let done=save.friends.includes('moonmoss');document.getElementById('questProgress').style.width=done?'100%':'0%';document.getElementById('questText').textContent=done?'Moonmoss is your friend!':'Make a new friend';document.getElementById('questNum').textContent=done?'1 / 1':'0 / 1';let friends=save.friends.map(id=>species.find(c=>c.id===id)).filter(Boolean);let html=friends.slice(0,3).map(c=>`<div class="friend-chip"><span>${c.emoji}</span><b>${c.name}</b></div>`).join('');while(friends.length<3){html+=`<div class="friend-chip empty-chip"><span>✧</span><b>To be met</b></div>`;friends.push(null)}document.getElementById('friendsRow').innerHTML=html}
function renderNearby(){let n=document.getElementById('nearby');if(nearbyCreature){let c=nearbyCreature;n.innerHTML=`<span class="face">${c.emoji}</span><div><b>${save.friends.includes(c.id)?c.name+' is here':c.name+' is nearby'}</b><small>${save.friends.includes(c.id)?'Your kindred spirit':'Tap HELLO to say hi'}</small></div><span class="dot"></span>`}else n.innerHTML='<span class="face">🌿</span><div><b>Someone\'s nearby</b><small>Explore to say hello</small></div><span class="dot"></span>'}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function modal(html){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal">${html}</section></div>`;document.getElementById('backdrop').addEventListener('pointerdown',e=>{if(e.target.id==='backdrop')closeModal()})}
function closeModal(){document.getElementById('modalRoot').innerHTML='';dialogueTarget=null}
function hello(){let c=nearbyCreature||species.slice().sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(c&&Math.hypot(c.x-player.x,c.y-player.y)<125)openMeet(c);else toast('Wander a little closer to someone ✨')}
function openMeet(c){dialogueTarget=c;let friend=save.friends.includes(c.id);modal(`<button class="close" onclick="closeModal()">×</button><div class="dialog-creature"><span class="big">${c.emoji}</span><div><b>${friend?'Your friend, ':''}${c.name}</b><small>${c.kind} · ${friend?'happy to see you again':'a curious new face'}</small></div></div><h2>${friend?'A familiar hello':'A gentle hello'}</h2><p class="sub">${friend?'You and '+c.name+' share a quiet moment together.':'You crouch down so you feel a little less tall. '+c.name+' watches you carefully.'}</p><div class="choice-actions"><button class="choice-action" onclick="kindness('berry')">🫐 &nbsp;${save.berries?'Offer a sweet berry':'Wish you had a berry…'} <small style="float:right;color:#849080">${save.berries} in satchel</small></button><button class="choice-action" onclick="kindness('song')">🎵 &nbsp;Hum a little tune</button><button class="choice-action" onclick="kindness('listen')">🌿 &nbsp;Sit quietly and listen</button></div>`)}
function kindness(type){let c=dialogueTarget;if(!c)return;if(save.friends.includes(c.id)){let words=type==='song'?'Your tune earns a happy little wiggle.':'The meadow feels softer with a friend beside you.';closeModal();toast(words);return}if(type==='berry'&&save.berries>0){save.berries--;saveIt()}else if(type==='berry'&&save.berries===0){toast('No berries yet — gather some in your satchel!');openMeet(c);return}let first=!save.friends.length;save.friends.push(c.id);if(!save.met.includes(c.id))save.met.push(c.id);saveIt();let reason=type==='berry'?'The berry is sweet, but your kindness is sweeter.':'Your gentle '+(type==='song'?'song':'patience')+' makes the little creature feel safe.';closeModal();setTimeout(()=>{modal(`<div style="text-align:center;font-size:52px;margin:2px 0">${c.emoji} <span style="color:#e4a77b">♡</span></div><h2 style="text-align:center">A friendship blooms!</h2><p class="sub" style="text-align:center">${reason} <b>${c.name}</b> chooses to stay by your side. No cages, no capture — just a new friend.</p><button class="primary" onclick="closeModal();toast('${first?'Your first kindred spirit!':'A new friendship, wonderfully made!'}')">${first?'Meet your new friend':'Keep wandering'} ✨</button></section>`);document.getElementById('backdrop').addEventListener('pointerdown',e=>{if(e.target.id==='backdrop')closeModal()})},120)}
function customize(first=false){let hairOpts=['🧑🏻‍🌾','🧑🏽‍🌾','🧑🏿‍🌾','👩🏻‍🌾','🧑🏼‍🦱'];let coatOpts=['#e68f71','#7799bd','#9b83b7','#6c9b76','#dfb95f'];modal(`<button class="close" onclick="closeModal()">×</button><h2>${first?'Your story starts here':'Make it your own'}</h2><p class="sub">Pick a name and a look for your meadow wanderer.</p><label class="field-label" for="nameInput">Your name</label><input id="nameInput" maxlength="16" class="name-input" value="${save.started?save.name:'Sage'}" placeholder="A name for your adventure"><label class="field-label">Choose your wanderer</label><div class="choices">${hairOpts.map(x=>`<button class="choice ${save.hair===x?'selected':''}" data-hair="${x}">${x}</button>`).join('')}</div><label class="field-label">Your favorite color</label><div>${coatOpts.map(x=>`<button class="color-choice ${save.coat===x?'selected':''}" data-coat="${x}" style="background:${x}" aria-label="Choose color"></button>`).join('')}</div><button class="primary" id="saveStyle">${first?'Step into the meadow':'Save my look'} ✨</button>`);document.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-hair]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.querySelectorAll('[data-coat]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-coat]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.getElementById('saveStyle').onclick=()=>{save.name=document.getElementById('nameInput').value.trim()||'Wanderer';save.hair=document.querySelector('[data-hair].selected')?.dataset.hair||save.hair;save.coat=document.querySelector('[data-coat].selected')?.dataset.coat||save.coat;save.started=true;saveIt();closeModal();if(first)toast('Welcome to Dappledell, '+save.name+'!')};}
function openJournal(){let cards=species.map(c=>`<div class="journal-item"><span class="big">${save.met.includes(c.id)||save.friends.includes(c.id)?c.emoji:'❔'}</span><div><b>${save.met.includes(c.id)||save.friends.includes(c.id)?c.name:'A mystery friend'}</b><small>${save.met.includes(c.id)||save.friends.includes(c.id)?c.blurb:'Wander through the meadow to discover this creature.'}</small></div><span class="status">${save.friends.includes(c.id)?'♡ FRIEND':save.met.includes(c.id)?'MET':'???'}</span></div>`).join('');modal(`<button class="close" onclick="closeModal()">×</button><h2>📖 &nbsp;Field notes</h2><p class="sub">Every creature has a story. Learn about them by meeting them gently.</p><div class="journal-list">${cards}</div><button class="primary" onclick="closeModal()">Back to the meadow</button>`)}
document.getElementById('customize').onclick=()=>customize(false);document.getElementById('openJournal').onclick=openJournal;document.getElementById('journalAction').onclick=openJournal;
document.getElementById('gather').onclick=()=>{save.berries++;saveIt();toast('You found a ripe meadow berry! 🫐')};document.getElementById('sing').onclick=()=>{if(nearbyCreature)toast('A tiny tune floats over to '+nearbyCreature.name+' 🎵');else toast('Your song drifts through the meadow 🎵')};document.getElementById('look').onclick=()=>toast('A breeze carries the scent of clover. 🌼');
let soundOn=false;document.getElementById('soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';toast(soundOn?'Meadow song on (ambient soon!)':'Sound off')};
renderUI();if(!save.started)customize(true);
</script>
</body></html>

