document.getElementById('touchAct').onclick=hello;
function renderUI(){document.getElementById('playerName').textContent=save.name;document.getElementById('avatar').textContent=save.hair;document.getElementById('berryCount').textContent=save.berries;document.getElementById('steps').textContent=Math.floor(save.steps);let done=save.friends.includes('moonmoss');document.getElementById('questProgress').style.width=done?'100%':'0%';document.getElementById('questText').textContent=done?'Moonmoss is your friend!':'Make a new friend';document.getElementById('questNum').textContent=done?'1 / 1':'0 / 1';let friends=save.friends.map(id=>species.find(c=>c.id===id)).filter(Boolean),html=friends.slice(0,3).map(c=>`<div class="friend-chip"><span>${c.emoji}</span><b>${c.name}</b></div>`).join('');while(friends.length<3){html+='<div class="friend-chip empty-chip"><span>✧</span><b>To be met</b></div>';friends.push(null)}document.getElementById('friendsRow').innerHTML=html}
function renderNearby(){let n=document.getElementById('nearby');if(nearbyCreature){let c=nearbyCreature;n.innerHTML=`<span class="face">${c.emoji}</span><div><b>${save.friends.includes(c.id)?c.name+' is here':c.name+' is nearby'}</b><small>${save.friends.includes(c.id)?'Your kindred spirit':'Tap HELLO to say hi'}</small></div><span class="dot"></span>`}else n.innerHTML='<span class="face">🌿</span><div><b>Someone\'s nearby</b><small>Explore to say hello</small></div><span class="dot"></span>'}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function modal(html){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal">${html}</section></div>`;document.getElementById('backdrop').addEventListener('pointerdown',e=>{if(e.target.id==='backdrop')closeModal()})}function closeModal(){document.getElementById('modalRoot').innerHTML='';dialogueTarget=null}
function hello(){let c=nearbyCreature||species.slice().sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(c&&Math.hypot(c.x-player.x,c.y-player.y)<125)openMeet(c);else toast('Wander a little closer to someone ✨')}
function openMeet(c){dialogueTarget=c;let friend=save.friends.includes(c.id);modal(`<button class="close" onclick="closeModal()">×</button><div class="dialog-creature"><span class="big">${c.emoji}</span><div><b>${friend?'Your friend, ':''}${c.name}</b><small>${c.kind} · ${friend?'happy to see you again':'a curious new face'}</small></div></div><h2>${friend?'A familiar hello':'A gentle hello'}</h2><p class="sub">${friend?'You and '+c.name+' share a quiet moment together.':'You crouch down so you feel a little less tall. '+c.name+' watches you carefully.'}</p><div class="choice-actions"><button class="choice-action" onclick="kindness('berry')">🫐 &nbsp;${save.berries?'Offer a sweet berry':'Wish you had a berry…'} <small style="float:right;color:#849080">${save.berries} in satchel</small></button><button class="choice-action" onclick="kindness('song')">🎵 &nbsp;Hum a little tune</button><button class="choice-action" onclick="kindness('listen')">🌿 &nbsp;Sit quietly and listen</button></div>`)}
function kindness(type){let c=dialogueTarget;if(!c)return;if(save.friends.includes(c.id)){closeModal();toast(type==='song'?'Your tune earns a happy little wiggle.':'The meadow feels softer with a friend beside you.');return}if(type==='berry'&&save.berries>0){save.berries--;saveIt()}else if(type==='berry'){toast('No berries yet — gather some in your satchel!');openMeet(c);return}let first=!save.friends.length;if(!save.met.includes(c.id))save.met.push(c.id);save.friends.push(c.id);saveIt();let reason=type==='berry'?'The berry is sweet, but your kindness is sweeter.':'Your gentle '+(type==='song'?'song':'patience')+' makes the little creature feel safe.';closeModal();setTimeout(()=>modal(`<div style="text-align:center;font-size:52px;margin:2px 0">${c.emoji} <span style="color:#e4a77b">♡</span></div><h2 style="text-align:center">A friendship blooms!</h2><p class="sub" style="text-align:center">${reason} <b>${c.name}</b> chooses to stay by your side. No cages, no capture — just a new friend.</p><button class="primary" onclick="closeModal();toast('${first?'Your first kindred spirit!':'A new friendship, wonderfully made!'}')">${first?'Meet your new friend':'Keep wandering'} ✨</button>`),120)}
function customize(first=false){let hairs=['🧑🏻‍🌾','🧑🏽‍🌾','🧑🏿‍🌾','👩🏻‍🌾','🧑🏼‍🦱'],colors=['#e68f71','#7799bd','#9b83b7','#6c9b76','#dfb95f'];modal(`<button class="close" onclick="closeModal()">×</button><h2>${first?'Your story starts here':'Make it your own'}</h2><p class="sub">Pick a name and a look for your meadow wanderer.</p><label class="field-label" for="nameInput">Your name</label><input id="nameInput" maxlength="16" class="name-input" value="${save.started?save.name:'Sage'}" placeholder="A name for your adventure"><label class="field-label">Choose your wanderer</label><div class="choices">${hairs.map(x=>`<button class="choice ${save.hair===x?'selected':''}" data-hair="${x}">${x}</button>`).join('')}</div><label class="field-label">Your favorite color</label><div>${colors.map(x=>`<button class="color-choice ${save.coat===x?'selected':''}" data-coat="${x}" style="background:${x}" aria-label="Choose color"></button>`).join('')}</div><button class="primary" id="saveStyle">${first?'Step into the meadow':'Save my look'} ✨</button>`);document.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-hair]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.querySelectorAll('[data-coat]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-coat]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.getElementById('saveStyle').onclick=()=>{save.name=document.getElementById('nameInput').value.trim()||'Wanderer';save.hair=document.querySelector('[data-hair].selected')?.dataset.hair||save.hair;save.coat=document.querySelector('[data-coat].selected')?.dataset.coat||save.coat;save.started=true;saveIt();closeModal();if(first)toast('Welcome to Dappledell, '+save.name+'!')}}
function openJournal(){let cards=species.map(c=>`<div class="journal-item"><span class="big">${save.met.includes(c.id)||save.friends.includes(c.id)?c.emoji:'❔'}</span><div><b>${save.met.includes(c.id)||save.friends.includes(c.id)?c.name:'A mystery friend'}</b><small>${save.met.includes(c.id)||save.friends.includes(c.id)?c.blurb:'Wander through the meadow to discover this creature.'}</small></div><span class="status">${save.friends.includes(c.id)?'♡ FRIEND':save.met.includes(c.id)?'MET':'???'}</span></div>`).join('');modal(`<button class="close" onclick="closeModal()">×</button><h2>📖 &nbsp;Field notes</h2><p class="sub">Every creature has a story. Learn about them by meeting them gently.</p><div class="journal-list">${cards}</div><button class="primary" onclick="closeModal()">Back to the meadow</button>`)}
document.getElementById('customize').onclick=()=>customize(false);document.getElementById('openJournal').onclick=openJournal;document.getElementById('journalAction').onclick=openJournal;document.getElementById('gather').onclick=()=>{save.berries++;saveIt();toast('You found a ripe meadow berry! 🫐')};document.getElementById('sing').onclick=()=>toast(nearbyCreature?'A tiny tune floats over to '+nearbyCreature.name+' 🎵':'Your song drifts through the meadow 🎵');document.getElementById('look').onclick=()=>toast('A breeze carries the scent of clover. 🌼');let soundOn=false;document.getElementById('soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';toast(soundOn?'Meadow song on':'Sound off')};renderUI();if(!save.started)customize(true);
</script></body></html>

